//! NGSI-LD vocabulary constants derived from the core context JSON at compile time.
//!
//! All constants are generated by the [`ngsi_ld_vocab_macros::generate_vocabulary!`] proc-macro,
//! which parses the embedded NGSI-LD v1.9 core context JSON and emits `pub const &'static str`
//! constants for every resolved term.  No runtime parsing, no `LazyLock`, no `expect()`.
//!
//! # Usage
//!
//! ```ignore
//! use crate::jsonld::vocab;
//! let iri: &str = vocab::CREATED_AT;
//! let prefix: &str = vocab::prefix::NGSI_LD;
//! let expanded: Option<&str> = vocab::compact_to_expanded("createdAt");
//! ```

ngsi_ld_vocab_macros::generate_vocabulary!("src/jsonld/context/ngsi-ld-core-context-v1.9.jsonld");

// External IRIs not present in the core context.

/// `urn:ngsi-ld:null` sentinel URI.
pub const NULL_URI: &str = "urn:ngsi-ld:null";

/// `https://uri.etsi.org/ngsi-ld/null` expanded null IRI.
pub const NULL_IRI: &str = "https://uri.etsi.org/ngsi-ld/null";

/// `http://www.w3.org/2001/XMLSchema#dateTime` XSD dateTime type.
pub const XSD_DATETIME: &str = "http://www.w3.org/2001/XMLSchema#dateTime";

/// `http://www.w3.org/ns/json-ld#context` JSON-LD context relation.
pub const JSONLD_CONTEXT_REL: &str = "http://www.w3.org/ns/json-ld#context";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn term_count_exceeds_150() {
        assert!(TERM_COUNT > 150, "expected >150 terms, got {}", TERM_COUNT);
    }

    #[test]
    fn compact_to_expanded_round_trips() {
        for &(compact, expanded) in COMPACT_TO_EXPANDED {
            let result = compact_to_expanded(compact);
            assert_eq!(result, Some(expanded), "compact_to_expanded failed for '{compact}'");
        }
    }

    #[test]
    fn expanded_to_compact_round_trips() {
        for &(expanded, compact) in EXPANDED_TO_COMPACT {
            let result = expanded_to_compact(expanded);
            assert_eq!(result, Some(compact), "expanded_to_compact failed for '{expanded}'");
        }
    }

    #[test]
    fn lookup_tables_are_sorted() {
        for window in COMPACT_TO_EXPANDED.windows(2) {
            assert!(
                window[0].0 < window[1].0,
                "COMPACT_TO_EXPANDED not sorted: {:?} >= {:?}",
                window[0].0,
                window[1].0
            );
        }
        for window in EXPANDED_TO_COMPACT.windows(2) {
            assert!(
                window[0].0 < window[1].0,
                "EXPANDED_TO_COMPACT not sorted: {:?} >= {:?}",
                window[0].0,
                window[1].0
            );
        }
    }

    #[test]
    fn known_term_constants_match_iris() {
        assert_eq!(PROPERTY, "https://uri.etsi.org/ngsi-ld/Property");
        assert_eq!(RELATIONSHIP, "https://uri.etsi.org/ngsi-ld/Relationship");
        assert_eq!(GEO_PROPERTY, "https://uri.etsi.org/ngsi-ld/GeoProperty");
        assert_eq!(HAS_VALUE, "https://uri.etsi.org/ngsi-ld/hasValue");
        assert_eq!(HAS_OBJECT, "https://uri.etsi.org/ngsi-ld/hasObject");
        assert_eq!(HAS_LANGUAGE_MAP, "https://uri.etsi.org/ngsi-ld/hasLanguageMap");
        assert_eq!(HAS_VOCAB, "https://uri.etsi.org/ngsi-ld/hasVocab");
        assert_eq!(HAS_JSON, "https://uri.etsi.org/ngsi-ld/hasJSON");
        assert_eq!(HAS_VALUE_LIST, "https://uri.etsi.org/ngsi-ld/hasValueList");
        assert_eq!(HAS_OBJECT_LIST, "https://uri.etsi.org/ngsi-ld/hasObjectList");
        assert_eq!(CREATED_AT, "https://uri.etsi.org/ngsi-ld/createdAt");
        assert_eq!(MODIFIED_AT, "https://uri.etsi.org/ngsi-ld/modifiedAt");
        assert_eq!(OBSERVED_AT, "https://uri.etsi.org/ngsi-ld/observedAt");
        assert_eq!(DELETED_AT, "https://uri.etsi.org/ngsi-ld/deletedAt");
        assert_eq!(DATASET_ID, "https://uri.etsi.org/ngsi-ld/datasetId");
        assert_eq!(INSTANCE_ID, "https://uri.etsi.org/ngsi-ld/instanceId");
        assert_eq!(UNIT_CODE, "https://uri.etsi.org/ngsi-ld/unitCode");
        assert_eq!(SCOPE, "https://uri.etsi.org/ngsi-ld/scope");
        assert_eq!(DATE_TIME, "https://uri.etsi.org/ngsi-ld/DateTime");
    }

    #[test]
    fn prefix_constants_are_correct() {
        assert_eq!(prefix::NGSI_LD, "https://uri.etsi.org/ngsi-ld/");
        assert_eq!(prefix::GEOJSON, "https://purl.org/geojson/vocab#");
    }

    #[test]
    fn external_iri_constants_are_correct() {
        assert_eq!(NULL_URI, "urn:ngsi-ld:null");
        assert_eq!(NULL_IRI, "https://uri.etsi.org/ngsi-ld/null");
        assert_eq!(XSD_DATETIME, "http://www.w3.org/2001/XMLSchema#dateTime");
        assert_eq!(JSONLD_CONTEXT_REL, "http://www.w3.org/ns/json-ld#context");
    }

    #[test]
    fn geojson_terms_resolve_to_purl_vocab() {
        assert!(COORDINATES.starts_with(prefix::GEOJSON));
        assert!(BBOX.starts_with(prefix::GEOJSON));
        assert!(GEOMETRY.starts_with(prefix::GEOJSON));
        assert!(FEATURES.starts_with(prefix::GEOJSON));
    }
}
